package main

import("database/sql";"log";"net/http";"time";"github.com/ditasetyakurniawan-droid/tropical-management-v1/internal/dbx";"github.com/ditasetyakurniawan-droid/tropical-management-v1/internal/httpx")
type app struct{db *sql.DB}; type sale struct{ID int64 `json:"id"`;BusinessDate string `json:"business_date"`;Orders int `json:"orders"`;Revenue float64 `json:"revenue"`;Channel string `json:"channel"`;CreatedAt time.Time `json:"created_at"`}
func main(){db,err:=dbx.Open(httpx.Env("SALES_DB_DSN","tropical:tropical@tcp(mysql:3306)/tropical_sales?parseTime=true&charset=utf8mb4"));if err!=nil{log.Fatal(err)};defer db.Close();a:=&app{db:db};if err:=a.migrate();err!=nil{log.Fatal(err)};mux:=http.NewServeMux();mux.HandleFunc("/healthz",func(w http.ResponseWriter,_ *http.Request){httpx.JSON(w,200,map[string]string{"status":"ok","service":"sales-service"})});mux.HandleFunc("/api/sales",a.sales);mux.HandleFunc("/internal/summary",a.summary);log.Println("sales-service listening on :8080");log.Fatal(http.ListenAndServe(":8080",mux))}
func(a *app)migrate()error{_,err:=a.db.Exec(`CREATE TABLE IF NOT EXISTS sales_entries(id BIGINT PRIMARY KEY AUTO_INCREMENT,business_date DATE NOT NULL,orders INT NOT NULL,revenue DECIMAL(14,2) NOT NULL,channel VARCHAR(60) NOT NULL DEFAULT 'dine-in',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_business_date(business_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);return err}
func(a *app)sales(w http.ResponseWriter,r *http.Request){switch r.Method{case http.MethodGet:rows,err:=a.db.Query("SELECT id,DATE_FORMAT(business_date,'%Y-%m-%d'),orders,revenue,channel,created_at FROM sales_entries ORDER BY business_date DESC,id DESC LIMIT 100");if err!=nil{httpx.JSON(w,500,map[string]string{"error":err.Error()});return};defer rows.Close();out:=[]sale{};for rows.Next(){var x sale;if rows.Scan(&x.ID,&x.BusinessDate,&x.Orders,&x.Revenue,&x.Channel,&x.CreatedAt)==nil{out=append(out,x)}};httpx.JSON(w,200,out);case http.MethodPost:var x sale;if httpx.DecodeJSON(r,&x)!=nil{httpx.JSON(w,400,map[string]string{"error":"invalid json"});return};if x.BusinessDate==""{x.BusinessDate=time.Now().Format("2006-01-02")};if x.Channel==""{x.Channel="dine-in"};res,err:=a.db.Exec("INSERT INTO sales_entries(business_date,orders,revenue,channel) VALUES(?,?,?,?)",x.BusinessDate,x.Orders,x.Revenue,x.Channel);if err!=nil{httpx.JSON(w,400,map[string]string{"error":"invalid sales data"});return};x.ID,_=res.LastInsertId();x.CreatedAt=time.Now();httpx.JSON(w,201,x);default:httpx.JSON(w,405,map[string]string{"error":"method not allowed"})}}
func(a *app)summary(w http.ResponseWriter,_ *http.Request){var revenue float64;var orders int;_ = a.db.QueryRow("SELECT COALESCE(SUM(revenue),0),COALESCE(SUM(orders),0) FROM sales_entries WHERE business_date=CURDATE()").Scan(&revenue,&orders);httpx.JSON(w,200,map[string]any{"sales_today":revenue,"orders_today":orders})}
